"use client";

import { loadFont as loadSans } from "@remotion/google-fonts/Inter";
import { memo, useMemo, useState } from "react";
import {
  AbsoluteFill,
  Easing,
  Img,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

export interface Sponsor {
  login: string;
  /** Optional avatar image; omitted entries render a deterministic initial badge. */
  avatarUrl?: string;
}

export interface GitHubSponsorsProps {
  /** Account shown in the header (github.com/sponsors/account). */
  account?: string;
  /** Current sponsors — every entry lands in the grid and ticks the goal bar. */
  sponsors?: Sponsor[];
  /** Sponsor goal the progress bar fills toward. */
  goal?: number;
  /** Milestone caption revealed under the card. */
  headline?: string;
  /** Goal-progress accent (bar fill + percent). */
  accentColor?: string;
  /** Sponsors heart color (GitHub-native pink). */
  heartColor?: string;
  speed?: number;
  theme?: "light" | "dark";
}

const FICTIONAL_LOGINS = [
  "danaships",
  "mira-oss",
  "tomo-dev",
  "acme-infra",
  "initech-tools",
  "globex-cloud",
  "vandelay-labs",
  "june-codes",
  "pax-runtime",
  "nils-b",
  "kioko-dev",
  "ada-frame",
  "remy-stack",
  "zephyr-ui",
  "quill-js",
  "arlo-nyx",
  "selin-k",
  "ferro-io",
  "wren-dev",
  "otis-cloud",
  "vega-ops",
  "ida-writes",
  "marlo-fm",
  "kaia-dev",
  "ruthenium",
  "pellucid",
  "novak-j",
  "tarn-io",
  "elio-dev",
  "sable-ink",
  "fenwick",
  "aria-oss",
  "dov-codes",
  "luma-dev",
  "pax-north",
  "gale-io",
  "tycho-labs",
  "imre-dev",
  "sona-ui",
  "brio-dev",
];

/** 40 fictional sponsors — pairs with the default goal of 50. */
export const SAMPLE_SPONSORS: Sponsor[] = FICTIONAL_LOGINS.map((login) => ({
  login,
}));

const { fontFamily: FONT_FAMILY } = loadSans("normal", {
  weights: ["400", "500", "600"],
  subsets: ["latin"],
});

const HEART_PATH =
  "M12.0001 4.52853C14.2745 2.23823 17.9866 2.23823 20.2611 4.52853C22.5784 6.86156 22.5784 10.667 20.2611 13.0001L12.0001 21.3199L3.73907 13.0001C1.42175 10.667 1.42175 6.86156 3.73907 4.52853C6.01353 2.23823 9.72563 2.23823 12.0001 4.52853Z";

const REF_W = 1280;
const REF_H = 720;

const CARD_W = 880;
const CARD_H = 460;
const CARD_X = (REF_W - CARD_W) / 2;
const CARD_Y = 104;
const HEADER_H = 64;
const FOOTER_H = 112;
const CARD_PAD = 28;

const GRID_BOX_W = CARD_W - CARD_PAD * 2 - 34;
const GRID_BOX_H = CARD_H - HEADER_H - FOOTER_H - 68;
const GRID_CX = REF_W / 2;
const GRID_CY = CARD_Y + HEADER_H + (CARD_H - HEADER_H - FOOTER_H) / 2;

const HEART_BASE = 150;
const HEART_DOCK_SIZE = 26;
const HEART_DOCK_X = CARD_X + CARD_PAD + HEART_DOCK_SIZE / 2;
const HEART_DOCK_Y = CARD_Y + HEADER_H / 2;

const DRAW_END = 40;
const PULSE_END = 62;
const HEART_DOCK_START = 52;
const HEART_DOCK_END = 84;
const AVATAR_START = 70;
const AVATAR_STEP = 3;
const AVATAR_DUR = 22;
const AVATAR_WINDOW = 56;
const FILL_START = AVATAR_START;
const FILL_END = AVATAR_START + AVATAR_WINDOW + AVATAR_DUR + 12;
const HEADLINE_START = 170;
const HEADLINE_DUR = 24;

interface Theme {
  surface: string;
  subtle: string;
  fg: string;
  fgMuted: string;
  border: string;
  track: string;
}

const THEMES: Record<"light" | "dark", Theme> = {
  light: {
    surface: "#FFFFFF",
    subtle: "#FAFAFA",
    fg: "#101828",
    fgMuted: "#667085",
    border: "#E4E7EC",
    track: "#F2F4F7",
  },
  dark: {
    surface: "#141417",
    subtle: "#0A0A0B",
    fg: "#FAFAFA",
    fgMuted: "#A1A1AA",
    border: "#26272B",
    track: "#26272B",
  },
};

export interface Point {
  x: number;
  y: number;
}

export function gridColumns(
  count: number,
  boxW = GRID_BOX_W,
  boxH = GRID_BOX_H,
): number {
  if (count <= 0) return 0;
  return Math.max(
    1,
    Math.min(count, Math.round(Math.sqrt((count * boxW) / boxH))),
  );
}

export function gridLayout(
  count: number,
  cols: number,
  cellW: number,
  cellH: number,
  cx = GRID_CX,
  cy = GRID_CY,
): Point[] {
  if (count <= 0 || cols <= 0) return [];
  const rows = Math.ceil(count / cols);
  const out: Point[] = [];
  for (let i = 0; i < count; i++) {
    const r = Math.floor(i / cols);
    const c = i % cols;
    const rowCount = Math.min(cols, count - r * cols);
    const rowW = (rowCount - 1) * cellW;
    const x = cx - rowW / 2 + c * cellW;
    const totalH = (rows - 1) * cellH;
    const y = cy - totalH / 2 + r * cellH;
    out.push({ x, y });
  }
  return out;
}

export function heartDrawProgress(frame: number, speed = 1): number {
  return interpolate(frame * speed, [0, DRAW_END], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.22, 1, 0.36, 1),
  });
}

export function heartPulseScale(frame: number, speed = 1): number {
  return interpolate(
    frame * speed,
    [DRAW_END - 2, DRAW_END + 6, DRAW_END + 17, PULSE_END],
    [1, 0.9, 1.06, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.inOut(Easing.ease),
    },
  );
}

/**
 * How many staggered items have landed by `frame`.
 * Item i starts at `start + i * step` and counts as landed `landAt`
 * frames later. Clamped to [0, total].
 */
export function landedCount(
  frame: number,
  total: number,
  start = AVATAR_START,
  step = AVATAR_STEP,
  landAt = AVATAR_DUR * 0.5,
): number {
  if (total <= 0) return 0;
  if (step <= 0) return frame >= start + landAt ? total : 0;
  const n = Math.floor((frame - start - landAt) / step) + 1;
  return Math.max(0, Math.min(total, n));
}

/** Fraction of the goal covered by `count`, clamped to [0, 1]. */
export function goalFillTarget(count: number, goal: number): number {
  if (goal <= 0) return 0;
  return Math.max(0, Math.min(1, count / goal));
}

/** Deterministic non-negative hash (djb2) for avatar tone selection. */
export function hashString(s: string): number {
  let h = 5381;
  for (let i = 0; i < s.length; i++) {
    h = ((h << 5) + h + s.charCodeAt(i)) >>> 0;
  }
  return h;
}

export interface AvatarTone {
  bg: string;
  fg: string;
}

const AVATAR_TONES: AvatarTone[] = [
  { bg: "#EFF4FF", fg: "#266DF0" },
  { bg: "#ECFDF3", fg: "#12B76A" },
  { bg: "#FFFAEB", fg: "#F79009" },
  { bg: "#FDF2FA", fg: "#C11574" },
  { bg: "#F4F3FF", fg: "#6938EF" },
  { bg: "#F2F4F7", fg: "#475467" },
];

/** Deterministic tone for an initial badge, derived from the login. */
export function avatarTone(login: string): AvatarTone {
  return AVATAR_TONES[hashString(login) % AVATAR_TONES.length];
}

function ramp(
  frame: number,
  speed: number,
  start: number,
  end: number,
  easing = Easing.bezier(0.22, 1, 0.36, 1),
): number {
  return interpolate(frame * speed, [start, end], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing,
  });
}

function Avatar({
  login,
  avatarUrl,
  size,
  theme,
  grayscale,
}: {
  login: string;
  avatarUrl?: string;
  size: number;
  theme: Theme;
  grayscale: number;
}) {
  const [errored, setErrored] = useState(false);
  const base = {
    width: size,
    height: size,
    borderRadius: 9999,
    border: `1px solid ${theme.border}`,
    flexShrink: 0,
    filter: `grayscale(${grayscale})`,
  } as const;

  if (errored || !avatarUrl) {
    const tone = avatarTone(login);
    return (
      <div
        style={{
          ...base,
          background: tone.bg,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          color: tone.fg,
          fontSize: size * 0.42,
          fontWeight: 600,
          fontFamily: FONT_FAMILY,
        }}
      >
        {login.charAt(0).toUpperCase()}
      </div>
    );
  }

  return (
    <Img
      src={avatarUrl}
      crossOrigin="anonymous"
      onError={() => setErrored(true)}
      style={{ ...base, objectFit: "cover" }}
    />
  );
}

const SponsorNode = memo(function SponsorNode({
  sponsor,
  cell,
  progress,
  size,
  theme,
}: {
  sponsor: Sponsor;
  cell: Point;
  progress: number;
  size: number;
  theme: Theme;
}) {
  return (
    <div
      style={{
        position: "absolute",
        left: cell.x,
        top: cell.y,
        translate: `-50% calc(-50% + ${(1 - progress) * 14}px)`,
        opacity: progress,
        filter: `blur(${(1 - progress) * 10}px)`,
        willChange: "translate, opacity, filter",
      }}
    >
      <Avatar
        login={sponsor.login}
        avatarUrl={sponsor.avatarUrl}
        size={size}
        theme={theme}
        grayscale={1 - progress}
      />
    </div>
  );
});

function HeartGlyph({
  size,
  color,
  draw,
  fill,
}: {
  size: number;
  color: string;
  draw: number;
  fill: number;
}) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      width={size}
      height={size}
    >
      <title>Sponsors heart</title>
      <path
        d={HEART_PATH}
        pathLength={1}
        fill={color}
        fillOpacity={fill}
        stroke={color}
        strokeWidth={1.4}
        strokeLinejoin="round"
        strokeLinecap="round"
        strokeDasharray={1}
        strokeDashoffset={1 - draw}
      />
    </svg>
  );
}

export function GitHubSponsors({
  account = "acme-labs",
  sponsors = SAMPLE_SPONSORS,
  goal = 50,
  headline = "Help Acme Labs reach 50 sponsors",
  accentColor = "#266DF0",
  heartColor = "#DB61A2",
  speed = 1,
  theme = "light",
}: GitHubSponsorsProps) {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const t = THEMES[theme] ?? THEMES.light;
  const stageScale = Math.min(width / REF_W, height / REF_H);

  const count = sponsors.length;
  const avatarStep =
    count > 1 ? Math.min(AVATAR_STEP, AVATAR_WINDOW / (count - 1)) : 0;
  const cols = gridColumns(count);
  const rows = Math.max(1, Math.ceil(count / Math.max(1, cols)));
  const cellW = GRID_BOX_W / Math.max(1, cols);
  const cellH = GRID_BOX_H / rows;
  const avatarSize = Math.min(64, Math.min(cellW, cellH) * 0.82);

  const cells = useMemo(
    () => gridLayout(count, cols, cellW, cellH),
    [count, cols, cellW, cellH],
  );

  const draw = heartDrawProgress(frame, speed);
  const fillO = ramp(frame, speed, DRAW_END - 8, PULSE_END, Easing.linear);
  const pulse = heartPulseScale(frame, speed);
  const dock = ramp(frame, speed, HEART_DOCK_START, HEART_DOCK_END);

  const landed = landedCount(
    frame * speed,
    count,
    AVATAR_START,
    avatarStep,
    AVATAR_DUR * 0.5,
  );
  const fillTarget = goalFillTarget(count, goal);
  const barFill = ramp(frame, speed, FILL_START, FILL_END) * fillTarget;
  const percent = Math.round(goalFillTarget(landed, goal) * 100);

  const headlineIn = ramp(
    frame,
    speed,
    HEADLINE_START,
    HEADLINE_START + HEADLINE_DUR,
  );

  return (
    <AbsoluteFill>
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          width: REF_W,
          height: REF_H,
          translate: "-50% -50%",
          scale: String(stageScale),
        }}
      >
        {/* Card chrome — fades in as the heart docks into the header */}
        <div
          style={{
            position: "absolute",
            left: CARD_X,
            top: CARD_Y,
            width: CARD_W,
            height: CARD_H,
            borderRadius: 10,
            background: t.surface,
            border: `1px solid ${t.border}`,
            boxShadow:
              theme === "light"
                ? "0 1px 2px rgba(16, 24, 40, 0.05)"
                : "0 1px 2px rgba(0, 0, 0, 0.4)",
            opacity: dock,
            translate: `0 ${(1 - dock) * 10}px`,
            willChange: "translate, opacity",
          }}
        >
          {/* Header */}
          <div
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              width: "100%",
              height: HEADER_H,
              display: "flex",
              alignItems: "center",
              padding: `0 ${CARD_PAD}px`,
              boxSizing: "border-box",
              borderBottom: `1px solid ${t.border}`,
              fontFamily: FONT_FAMILY,
            }}
          >
            {/* Space reserved for the docked heart */}
            <div style={{ width: HEART_DOCK_SIZE + 12, flexShrink: 0 }} />
            <div
              style={{
                fontSize: 19,
                fontWeight: 600,
                letterSpacing: "-0.01em",
                color: t.fg,
              }}
            >
              Sponsors
            </div>
            <div
              style={{
                marginLeft: 10,
                padding: "2px 10px",
                borderRadius: 9999,
                background: t.track,
                border: `1px solid ${t.border}`,
                fontSize: 14,
                fontWeight: 600,
                color: t.fgMuted,
                fontVariantNumeric: "tabular-nums",
              }}
            >
              {landed}
            </div>
            <div
              style={{
                marginLeft: "auto",
                fontSize: 15,
                fontWeight: 400,
                color: t.fgMuted,
              }}
            >
              github.com/sponsors/{account}
            </div>
          </div>

          {/* Goal footer */}
          <div
            style={{
              position: "absolute",
              left: 0,
              bottom: 0,
              width: "100%",
              height: FOOTER_H,
              padding: `0 ${CARD_PAD}px`,
              boxSizing: "border-box",
              borderTop: `1px solid ${t.border}`,
              display: "flex",
              flexDirection: "column",
              justifyContent: "center",
              gap: 12,
              fontFamily: FONT_FAMILY,
            }}
          >
            <div
              style={{
                display: "flex",
                alignItems: "baseline",
                justifyContent: "space-between",
              }}
            >
              <div style={{ fontSize: 16, fontWeight: 500, color: t.fgMuted }}>
                Sponsor goal
              </div>
              <div
                style={{
                  fontSize: 16,
                  fontWeight: 600,
                  letterSpacing: "-0.01em",
                  color: t.fg,
                  fontVariantNumeric: "tabular-nums",
                }}
              >
                {landed} of {goal} sponsors{" "}
                <span style={{ color: accentColor }}>· {percent}%</span>
              </div>
            </div>
            <div
              style={{
                width: "100%",
                height: 8,
                borderRadius: 9999,
                background: t.track,
                overflow: "hidden",
              }}
            >
              <div
                style={{
                  width: `${barFill * 100}%`,
                  height: "100%",
                  borderRadius: 9999,
                  background: accentColor,
                  willChange: "width",
                }}
              />
            </div>
          </div>
        </div>

        {/* Sponsor avatars */}
        {sponsors.map((sponsor, i) => (
          <SponsorNode
            key={`node-${sponsor.login}-${i}`}
            sponsor={sponsor}
            cell={cells[i]}
            progress={ramp(
              frame,
              speed,
              AVATAR_START + i * avatarStep,
              AVATAR_START + i * avatarStep + AVATAR_DUR,
            )}
            size={avatarSize}
            theme={t}
          />
        ))}

        {/* Heart — draws large over the grid, then docks into the header */}
        <div
          style={{
            position: "absolute",
            left: GRID_CX,
            top: GRID_CY,
            width: HEART_BASE,
            height: HEART_BASE,
            translate: `calc(-50% + ${(HEART_DOCK_X - GRID_CX) * dock}px) calc(-50% + ${
              (HEART_DOCK_Y - GRID_CY) * dock
            }px)`,
            scale: String(
              (1 - (1 - HEART_DOCK_SIZE / HEART_BASE) * dock) * pulse,
            ),
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            willChange: "transform",
          }}
        >
          <HeartGlyph
            size={HEART_BASE}
            color={heartColor}
            draw={draw}
            fill={fillO}
          />
        </div>

        {/* Milestone caption */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: CARD_Y + CARD_H + 34,
            width: REF_W,
            textAlign: "center",
            fontFamily: FONT_FAMILY,
            fontSize: 30,
            fontWeight: 600,
            letterSpacing: "-0.015em",
            color: t.fg,
            opacity: headlineIn,
            translate: `0 ${(1 - headlineIn) * 12}px`,
            filter: `blur(${(1 - headlineIn) * 10}px)`,
            willChange: "translate, opacity, filter",
          }}
        >
          {headline}
        </div>
      </div>
    </AbsoluteFill>
  );
}
